from typing import List
from collections import deque

def numBusesToDestination(routes: List[List[int]], S: int, T: int) -> int:
    if S == T:
        return 0 if any(S in route for route in routes) else -1

    if not any(T in route for route in routes):
        return -1

    stop_to_routes = {}
    for route_idx, route in enumerate(routes):
        for stop in route:
            if stop not in stop_to_routes:
                stop_to_routes[stop] = set()
            stop_to_routes[stop].add(route_idx)

    if S not in stop_to_routes or T not in stop_to_routes:
        return -1

    if S == T:
        return 0

    visited_routes = set()
    queue = deque()
    for route_idx in stop_to_routes[S]:
        queue.append((route_idx, 1))
        visited_routes.add(route_idx)

    while queue:
        current_route, buses_taken = queue.popleft()
        for stop in routes[current_route]:
            if stop == T:
                return buses_taken
            for next_route in stop_to_routes[stop]:
                if next_route not in visited_routes:
                    visited_routes.add(next_route)
                    queue.append((next_route, buses_taken + 1))
    return -1
